mapper.select:
SELECT ips.id ,COALESCE(fi.fund_name, ips.fund_name) AS fundName ,ips.fund_code ,ips.adjuster_name ,ips.entry_time ,ips.target_pool_id ,ips.adjust_log_id ,ips.adjust_batch_no ,p.pool_name AS targetPoolName ,ips.security_type ,dst.security_type_name ,fi.fund_manager_names ,fi.fund_administrator ,fi.fund_custodian ,fi.establishment_date ,fi.issue_term ,fi.latest_nav ,fi.accumulated_nav ,fi.daily_ten_thousand_income ,fi.seven_day_annualized_yield ,fi.latest_scale ,fi.previous_close_price ,fi.premium_discount_rate FROM ip_pool_status_fund ips LEFT JOIN ip_investment_pool p ON ips.target_pool_id = p.id AND p.is_deleted = 0 LEFT JOIN rrs_fundinfo fi ON ips.fund_code = fi.fund_code AND fi.is_deleted = 0 INNER JOIN dict_security_type dst ON dst.security_type = ips.security_type AND dst.category_type = 'fund' AND dst.is_deleted = 0
ips.is_deleted = 0 AND ips.audit_status = '20'
AND ips.target_pool_id IN
#{poolId}
AND ips.fund_code LIKE CONCAT('%', #{fundCode}, '%')
AND (COALESCE(fi.fund_name, ips.fund_name) LIKE CONCAT('%', #{fundName}, '%') OR COALESCE(fi.fund_short_name, ips.fund_short_name) LIKE CONCAT('%', #{fundName}, '%'))
AND ips.security_type = #{securityType}
AND ips.entry_time >= #{entryTimeStart}
AND ips.entry_time <= #{entryTimeEnd}
AND ips.adjuster_name LIKE CONCAT('%', #{adjusterName}, '%')
ORDER BY ips.entry_time DESC ,ips.id DESC
